-- The 975 traders our copy of made over 2.5% a month in the backtest (research, 2026-10-11:
-- all 9 342 accounts at a profit over the month before, their last up to 90 days, our latency,
-- slippage and fees), with what the backtest expects of their copies, to set the paper copies
-- against.
CREATE TABLE IF NOT EXISTS backtest_picks (
    address           text        PRIMARY KEY,
    picked_at         timestamptz NOT NULL DEFAULT now(),
    style             text        NOT NULL,
    copy_roi_month    float8      NOT NULL,
    copy_trips        integer     NOT NULL,
    boot5_month       float8,
    copy_roi_last30   float8,
    trips_last30      integer,
    win               float8,
    trader_month_pnl  float8,
    account_value     float8
);
ON CONFLICT (address) DO NOTHING;
